const crypto = require('crypto');
const root = $json && typeof $json === 'object' ? $json : {};
const top = root.body && typeof root.body === 'object' ? root.body : root;
const data = top.data && typeof top.data === 'object' ? top.data : top;
const key = (data.key && typeof data.key === 'object') ? data.key : ((top.key && typeof top.key === 'object') ? top.key : {});
const msg = (data.message && typeof data.message === 'object') ? data.message : ((top.message && typeof top.message === 'object') ? top.message : {});

const messageText =
  msg.conversation ||
  (msg.extendedTextMessage && msg.extendedTextMessage.text) ||
  '';
const messageType = data.messageType || top.messageType || null;

const instance = top.instance || root.instance || '';

let waJid = key.remoteJid || top.sender || root.sender || '';
let phoneRaw = '';
if (typeof waJid === 'string' && waJid) {
  phoneRaw = waJid.split('@')[0].replace(/[^0-9]/g, '');
}
if (!phoneRaw && top.number) {
  phoneRaw = String(top.number || '').replace(/[^0-9]/g, '');
}

let phoneE164 = '';
if (phoneRaw) {
  if (phoneRaw.startsWith('55')) phoneE164 = `+${phoneRaw}`;
  else if (phoneRaw.length >= 10) phoneE164 = `+55${phoneRaw}`;
  else phoneE164 = `+${phoneRaw}`;
}

const unitSlugRaw = String(top.unitSlug || instance || process.env.N8N_DEFAULT_UNIT_SLUG || 'default').trim().toLowerCase();
const unitSlug = unitSlugRaw.replace(/[^a-z0-9_]+/g, '_').replace(/^_+|_+$/g, '') || 'default';
let unitName = unitSlug;
try {
  const map = process.env.N8N_UNIT_NAME_MAP ? JSON.parse(process.env.N8N_UNIT_NAME_MAP) : {};
  unitName = map[unitSlug] || process.env.N8N_DEFAULT_UNIT_NAME || unitSlug;
} catch (e) {
  unitName = process.env.N8N_DEFAULT_UNIT_NAME || unitSlug;
}

const rawText = messageText || '';
const normalized = rawText.toLowerCase().trim();
const isOptOut = /(parar|sair|stop|cancelar mensagens)/i.test(normalized);
const wantsHuman = /(atendente|humano)/i.test(normalized);
const isPrice = /(preço|preco|valor|custo|quanto)/i.test(normalized);
const isFear = /(medo|receio|insegur)/i.test(normalized);
const isAudioLong = messageType && messageType !== 'conversation' && rawText.length === 0;
const selection = ['1', '2', '3'].includes(normalized) ? normalized : null;
const confirmYes = /^(sim|s)$/i.test(normalized);
const confirmNo = /^(nao|não|n)$/i.test(normalized);

const pushName = data.pushName || top.pushName || null;

let messageId = key.id || data.messageId || top.messageId || root.messageId || null;
if (!messageId) {
  const ts = data.messageTimestamp || top.messageTimestamp || top.date_time || new Date().toISOString();
  const source = JSON.stringify({ phone: phoneRaw, ts, text: rawText });
  messageId = `derived:${crypto.createHash('sha256').update(source).digest('hex').slice(0, 32)}`;
}

const shouldProcess = Boolean(rawText) && key.fromMe !== true;

function esc(v) {
  return String(v || '').replace(/'/g, "''");
}

return [{
  json: {
    raw_payload: root,
    raw_payload_sql: esc(JSON.stringify(root || {})),
    message_text: rawText,
    message_text_sql: esc(rawText || ''),
    message_type: messageType,
    message_id: messageId,
    from_me: !!key.fromMe,
    push_name: pushName,
    push_name_sql: esc(pushName || ''),
    phone_raw: phoneRaw || null,
    phone_e164: phoneE164 || null,
    unit_slug: unitSlug || null,
    unit_name: unitName || null,
    is_opt_out: isOptOut,
    wants_human: wantsHuman,
    is_price: isPrice,
    is_fear: isFear,
    is_audio_long: isAudioLong,
    selection,
    confirm_yes: confirmYes,
    confirm_no: confirmNo,
    should_process: shouldProcess
  }
}];

