parameters.jsCode:
const parse = $node["02_Parse_Evolution"].json;
const db = $node["03_DB_Init"].json || {};
const slotsRow = $node["19_Fetch_Last_Slots"].json || {};
const slots = Array.isArray(slotsRow.slots) ? slotsRow.slots : [];

const text = (parse.message_text || '').trim();
const lower = text.toLowerCase();
const triageStep = Number(db.triage_step || 0);
let triageData = db.triage_data || {};
if (typeof triageData === 'string') {
  try { triageData = JSON.parse(triageData); } catch { triageData = {}; }
}

const assistant = 'Quer falar com atendente? (Digite ATENDENTE)';
const unitName = parse.unit_name || 'nossa clínica';

const reply = (line1, line2) => `${line1}
${line2} ${assistant}`.trim();

let nextAction = 'noop';
let replyText = null;
let newStatus = db.funnel_status || 'novo_lead';
let triageEvent = null;
let nextStep = triageStep;
let schedulePayload = null;
let slot = null;
let handoffReason = null;

if (parse.wants_human) {
  nextAction = 'handoff';
  handoffReason = 'user_requested';
} else if ((db.funnel_status === 'agendamento_sugerido' || db.funnel_status === 'qualificado') && parse.selection && slots.length) {
  nextAction = 'schedule_confirm';
  const idx = Number(parse.selection) - 1;
  slot = slots[idx] || slots[0];
  schedulePayload = {
    contact_id: db.contact_id,
    conversation_id: db.conversation_id,
    unit_slug: parse.unit_slug,
    unit_name: unitName,
    phone_e164: parse.phone_e164
  };
} else if (parse.is_price) {
  nextAction = 'reply';
  replyText = reply('Temos faixas de valores que variam por avaliação.', 'Posso te ajudar a agendar uma avaliação rápida?');
} else if (parse.is_fear) {
  nextAction = 'reply';
  replyText = reply('Entendo sua preocupação.', 'A avaliação é feita com profissional habilitado para orientar com segurança.');
} else if (parse.is_audio_long) {
  nextAction = 'reply';
  replyText = reply('Recebi seu áudio.', 'Pode resumir em 1 frase o que você busca?');
} else if (triageStep <= 0) {
  nextAction = 'reply';
  replyText = reply(`Oi! Sou a assistente da ${unitName}.`, 'Você procura estética Facial ou Corporal? (Responda: Facial/Corporal)');
  nextStep = 1;
  newStatus = 'em_triagem';
  triageEvent = 'triage_started';
} else if (triageStep === 1) {
  if (lower.includes('facial') || lower.includes('corporal')) {
    triageData.area = lower.includes('corporal') ? 'corporal' : 'facial';
    nextAction = 'reply';
    replyText = reply('Perfeito.', 'Qual procedimento você quer? (Ex: harmonização, bioestimulador, lipo enzimática)');
    nextStep = 2;
    newStatus = 'em_triagem';
    triageEvent = 'triage_answered';
  } else {
    nextAction = 'handoff';
    handoffReason = 'out_of_script_area';
  }
} else if (triageStep === 2) {
  triageData.procedure = text || null;
  nextAction = 'reply';
  replyText = reply('Entendi.', 'É pra quando? (Hoje/Essa semana/Sem pressa)');
  nextStep = 3;
  newStatus = 'em_triagem';
  triageEvent = 'triage_answered';
} else if (triageStep === 3) {
  triageData.urgency = text || null;
  nextAction = 'reply';
  replyText = reply('Ótimo.', 'Quais períodos você prefere? (Manhã/Tarde/Noite) e quais dias?');
  nextStep = 4;
  newStatus = 'em_triagem';
  triageEvent = 'triage_answered';
} else {
  triageData.preferences = text || null;
  nextAction = 'schedule';
  newStatus = 'qualificado';
  triageEvent = 'triage_completed';
  schedulePayload = {
    contact_id: db.contact_id,
    conversation_id: db.conversation_id,
    unit_slug: parse.unit_slug,
    unit_name: unitName,
    phone_e164: parse.phone_e164,
    preferences: triageData.preferences
  };
}

function esc(v) {
  return String(v || '').replace(/'/g, "''");
}

return [{ json: {
  next_action: nextAction,
  reply_text: replyText,
  reply_text_sql: esc(replyText || ''),
  new_status: newStatus,
  triage_event: triageEvent,
  next_step: nextStep,
  triage_data: triageData,
  triage_data_sql: esc(JSON.stringify(triageData || {})),
  schedule_payload: schedulePayload,
  slot,
  handoff_reason: handoffReason,
  handoff_reason_sql: esc(handoffReason || '')
} }];

